// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address _newOwner, address _attacker) public {
        vm.assume(_newOwner != address(0));
        vm.assume(_attacker != address(0));
        vm.assume(_newOwner != _attacker);
        address originalOwner = c.owner();
        vm.prank(_attacker);
        try c.transferOwnership(_newOwner) { } catch { }
        assertTrue(c.owner() == originalOwner);
    }
}
